import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Ветеринарная клиника: запись к врачу, карточка питомца и напоминания о прививках"}>
      <p>{"Ветеринарная клиника в Перми, три врача и груминг по выходным. Хотим, чтобы владельцы животных записывались онлайн: выбирают питомца, услугу (приём терапевта, вакцинация, УЗИ, груминг) и врача, видят свободное время и записываются. В кабинете владельца — карточки питомцев: вид, порода, дата рождения, вес, прививки с датами. За неделю до следующей прививки владельцу приходит напоминание с кнопкой записи, за день до приёма — ещё одно. Врач видит своё расписание и после приёма пишет короткое заключение и следующую прививку — владелец видит это в кабинете. Администратор видит всё и записывает по телефону. На сайте — услуги с ценами, врачи, советы по уходу и как доехать. Экстренные случаи — только по телефону, это надо написать крупно. С иностранными студентами-владельцами у нас переписывается клиент, её почта клиент."}</p>
      <ul>
        <li>{"Онлайн-запись"}</li>
        <li>{"Карточка питомца"}</li>
        <li>{"Напоминание о прививке"}</li>
        <li>{"Заключение врача в кабинете"}</li>
      </ul>
      <p>{"Владелец видит только своих питомцев"}</p>
      <p>{"Напоминание за неделю до прививки"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
